From 3040fc9656f9e792b3587ae22f9382d2a0fb3bfc Mon Sep 17 00:00:00 2001
From: magnum <john.magnum@hushmail.com>
Date: Thu, 20 Dec 2012 01:17:50 +0100
Subject: [PATCH] Fix a bug introduced in ef133e4 where a system with
 OS_TIMER=0 would run into problems when the formats called
 sig_timer_emu_tick() during benchmark. To fix this, I made bench_running a
 global variable. Maybe there are better ways. This patch also fixes a minor
 bug in erasing the "spinning wheel".


diff --git a/src/common-opencl.c b/src/common-opencl.c
index 257567306..f625d453d 100644
--- a/src/common-opencl.c
+++ b/src/common-opencl.c
@@ -18,28 +18,33 @@ static char *kernel_source;
 static int kernel_loaded;
 static size_t program_size;

+extern volatile int bench_running;
+
 void opencl_process_event(void)
 {
+	if (!bench_running) {
 #if !OS_TIMER
-	sig_timer_emu_tick();
+		sig_timer_emu_tick();
 #endif
-	if (event_pending) {
-		if (event_save) {
-			event_save = 0;
-			rec_save();
-		}
+		if (event_pending) {

-		if (event_status) {
-			event_status = 0;
-			status_print();
-		}
+			event_pending = event_abort;

-		if (event_ticksafety) {
-			event_ticksafety = 0;
-			status_ticks_overflow_safety();
-		}
+			if (event_save) {
+				event_save = 0;
+				rec_save();
+			}

-		event_pending = event_abort;
+			if (event_status) {
+				event_status = 0;
+				status_print();
+			}
+
+			if (event_ticksafety) {
+				event_ticksafety = 0;
+				status_ticks_overflow_safety();
+			}
+		}
 	}
 }


diff --git a/src/cracker.c b/src/cracker.c
index 0f9c1d845..9a8e416d6 100644
--- a/src/cracker.c
+++ b/src/cracker.c
@@ -66,6 +66,11 @@ void crk_init(struct db_main *db, void (*fix_state)(void),
 		error();
 	}

+#ifdef CL_VERSION_1_0
+	/* This erases the 'spinning wheel' cursor from self-test */
+	fprintf(stderr, " \b");
+#endif
+
 	crk_db = db;
 	memcpy(&crk_params, &db->format->params, sizeof(struct fmt_params));
 	memcpy(&crk_methods, &db->format->methods, sizeof(struct fmt_methods));
-- 
2.25.1



diff --git a/src/bench.c b/src/bench.c
index 8bb6b70fd..3d8e9b13f 100644
--- a/src/bench.c
+++ b/src/bench.c
@@ -72,7 +72,7 @@ void clk_tck_init(void)

 unsigned int benchmark_time = BENCHMARK_TIME;

-static volatile int bench_running;
+volatile int bench_running;

 static void bench_handle_timer(int signum)
 {
@@ -257,10 +257,6 @@ char *benchmark_format(struct fmt_main *format, int salts,
 	if (end_virtual == start_virtual) end_virtual++;
 	results->virtual = end_virtual - start_virtual;
 #endif
-#ifdef CL_VERSION_1_0
-	/* This erases the 'spinning wheel' cursor from self-test */
-	fprintf(stderr, " \b");
-#endif

 	results->real = end_real - start_real;
 	results->count = count;

